(function(){'use strict';
var STATE_KEY='welog-pair-sheet-v4',sheet=document.getElementById('sheet');if(!sheet)return;
function getState(){try{return JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}}catch(e){return{}}}
function strip(root){root.querySelectorAll('.direct-bounds-overlay-fixed,.welog-layout-overlay-fixed,.welog-layout-hud,.st-toolbar,.st-resize,.st-rotate,.st-v2-lock,.st-v2-del,.st-v2-resize,.direct-crop-ui,.guide-line').forEach(function(n){n.remove()});root.querySelectorAll('.direct-sticker').forEach(function(n){n.style.outline='none'})}
function copyLiveTypography(src,dst){function walk(a,b){if(!a||!b)return;if(a.nodeType===1&&b.nodeType===1){var c=getComputedStyle(a);['font-family','font-weight','font-style','font-size','line-height','letter-spacing','word-spacing'].forEach(function(p){b.style.setProperty(p,c.getPropertyValue(p),'important')})}var ac=a.childNodes,bc=b.childNodes,n=Math.min(ac.length,bc.length);for(var i=0;i<n;i++)walk(ac[i],bc[i])}walk(src,dst)}
function modal(){var old=document.querySelector('.welog-exact-shot');if(old)old.remove();var m=document.createElement('div');m.className='welog-exact-shot';m.innerHTML='<section class="welog-exact-shot-dialog"><header class="welog-exact-shot-head"><div><small>PREVIEW</small><b>작업 화면 미리보기</b></div><button type="button" aria-label="닫기">×</button></header><div class="welog-exact-shot-body"><div class="welog-preview-host"></div></div></section>';document.body.appendChild(m);m.addEventListener('click',function(e){if(e.target===m||e.target.closest('.welog-exact-shot-head button'))m.remove()});return m}
function preview(){var m=modal(),body=m.querySelector('.welog-exact-shot-body'),host=m.querySelector('.welog-preview-host'),clone=sheet.cloneNode(true),cs=getComputedStyle(sheet),w=sheet.offsetWidth,h=sheet.offsetHeight;clone.removeAttribute('id');strip(clone);clone.classList.add('welog-preview-live-clone');clone.style.setProperty('width',w+'px','important');clone.style.setProperty('height',h+'px','important');clone.style.setProperty('margin','0','important');clone.style.setProperty('transform','none','important');clone.style.setProperty('zoom','1','important');clone.style.setProperty('box-shadow',cs.boxShadow,'important');clone.style.setProperty('border-radius',cs.borderRadius,'important');host.appendChild(clone);requestAnimationFrame(function(){var aw=Math.max(1,body.clientWidth-32),ah=Math.max(1,body.clientHeight-32),sc=Math.min(1,aw/w,ah/h);host.style.width=(w*sc)+'px';host.style.height=(h*sc)+'px';clone.style.setProperty('transform','scale('+sc+')','important');clone.style.setProperty('transform-origin','top left','important')})}
async function ready(){if(document.fonts){try{await document.fonts.ready}catch(e){}}var imgs=[].slice.call(sheet.querySelectorAll('img'));await Promise.all(imgs.map(function(im){if(im.complete)return Promise.resolve();return new Promise(function(r){im.addEventListener('load',r,{once:true});im.addEventListener('error',r,{once:true});setTimeout(r,2500)})}));await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})})}
function size(){var t=sheet.style.transform,z=sheet.style.zoom;sheet.style.transform='none';sheet.style.zoom='1';var w=sheet.offsetWidth,h=sheet.offsetHeight;sheet.style.transform=t;sheet.style.zoom=z;return{w:w,h:h}}
function transparentRound(src,w){var ratio=src.width/Math.max(1,w),radius=parseFloat(getComputedStyle(sheet).borderRadius)||0,r=Math.max(0,radius*ratio),out=document.createElement('canvas');out.width=src.width;out.height=src.height;var c=out.getContext('2d');c.clearRect(0,0,out.width,out.height);c.save();c.beginPath();if(c.roundRect)c.roundRect(0,0,out.width,out.height,r);else{c.moveTo(r,0);c.arcTo(out.width,0,out.width,out.height,r);c.arcTo(out.width,out.height,0,out.height,r);c.arcTo(0,out.height,0,0,r);c.arcTo(0,0,out.width,0,r);c.closePath()}c.clip();c.drawImage(src,0,0);c.restore();return out}
async function capture(){await ready();if(!window.html2canvas)throw new Error('html2canvas unavailable');var sz=size(),clone=sheet.cloneNode(true);copyLiveTypography(sheet,clone);strip(clone);clone.setAttribute('data-welog-export-clone','true');clone.style.setProperty('position','fixed','important');clone.style.setProperty('left','-100000px','important');clone.style.setProperty('top','0','important');clone.style.setProperty('width',sz.w+'px','important');clone.style.setProperty('height',sz.h+'px','important');clone.style.setProperty('margin','0','important');clone.style.setProperty('transform','none','important');clone.style.setProperty('zoom','1','important');clone.style.setProperty('box-shadow','none','important');clone.style.setProperty('pointer-events','none','important');document.body.appendChild(clone);try{await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})});var raw=await window.html2canvas(clone,{scale:2,useCORS:true,allowTaint:false,backgroundColor:null,logging:false,imageTimeout:30000,width:sz.w,height:sz.h,scrollX:0,scrollY:0,windowWidth:Math.max(window.innerWidth,sz.w+64),windowHeight:Math.max(window.innerHeight,sz.h+64)});return transparentRound(raw,sz.w)}finally{clone.remove()}}
async function save(){var btn=document.getElementById('printBtn');if(!btn)return;var old=btn.textContent;btn.disabled=true;btn.textContent='저장 중…';try{var canvas=await capture(),blob=await new Promise(function(res,rej){canvas.toBlob(function(b){b?res(b):rej(new Error('blob'))},'image/png')});var u=URL.createObjectURL(blob),a=document.createElement('a'),n=(getState().pairName||'WeLog').trim()||'WeLog';a.href=u;a.download=n+'.png';document.body.appendChild(a);a.click();setTimeout(function(){a.remove();URL.revokeObjectURL(u)},1200)}catch(e){console.error(e);alert('PNG 저장에 실패했습니다. 다시 시도해 주세요.')}finally{btn.disabled=false;btn.textContent=old}}
function bind(id,fn){var b=document.getElementById(id);if(!b)return;var n=b.cloneNode(true);b.replaceWith(n);n.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();fn()},true)}bind('previewBtn',preview);bind('printBtn',save);
})();